			"Office.ICTPFactory": {"displayName":"ICTPFactory","members":[{"name":"CreateCTP","kind":"method","signature":"CreateCTP(CTPAxID As String, CTPTitle As String, [CTPParentWindow As Variant]) As _CustomTaskPane","doc":{"summary":"Creates an instance of a custom task pane.","params":[{"name":"CTPAxID","text":"The CLSID or ProgID of a Microsoft ActiveX object.","type":"String"},{"name":"CTPTitle","text":"The title for the task pane.","type":"String"},{"name":"CTPParentWindow","text":"The window that hosts the task pane. If not present, the parent of the task pane is the ActiveWindow of the host application.","type":"Variant"}],"source":"external"}}],"doc":{"summary":"Used to create a custom task pane.","example":"public class Connect : Object, Extensibility.IDTExtensibility2, ICustomTaskPaneConsumer\n...\nobject missing = Type.Missing;\npublic CustomTaskPane CTP = null;\n\npublic void CTPFactoryAvailable(ICTPFactory CTPFactoryInst)\n{\n CTP = CTPFactoryInst.CreateCTP(\"SampleActiveX.myControl\", \"Task Pane Example\", missing);\n sampleAX = (myControl)CTP.ContentControl;\n sampleAX.InsertTextClicked += new InsertTextEventHandler(sampleAX_InsertTextClicked);\n CTP.Visible = true;\n}\n...","params":[],"source":"external"}},
			"Office.ICustomTaskPaneConsumer": {"displayName":"ICustomTaskPaneConsumer","members":[{"name":"CTPFactoryAvailable","kind":"method","signature":"CTPFactoryAvailable(CTPFactoryInst As ICTPFactory)","doc":{"summary":"Passes an ICTPFactory object to a Microsoft ActiveX add-in that can then be used when creating a custom task pane.","params":[{"name":"CTPFactoryInst","text":"The object is used by an add-in to create a task pane.","type":"ICTPFactory"}],"source":"external"}}],"doc":{"summary":"An interface that provides access to the CTPFactoryAvailable method that is used to create an instance of a custom task pane.","example":"public class Connect : Object, Extensibility.IDTExtensibility2, ICustomTaskPaneConsumer\n...\nobject missing = Type.Missing;\npublic CustomTaskPane CTP = null;\n\npublic void CTPFactoryAvailable(ICTPFactory CTPFactoryInst)\n{\n CTP = CTPFactoryInst.CreateCTP(\"SampleActiveX.myControl\", \"Task Pane Example\", missing);\n sampleAX = (myControl)CTP.ContentControl;\n sampleAX.InsertTextClicked += new InsertTextEventHandler(sampleAX_InsertTextClicked);\n CTP.Visible = true;\n}\n...","params":[],"source":"external"}},
