			"Office.LabelInfo": {"displayName":"LabelInfo","members":[{"name":"ActionId","kind":"property","declaredType":"String","access":"read/write"},{"name":"Application","kind":"property","declaredType":"Object","access":"read-only"},{"name":"AssignmentMethod","kind":"property","declaredType":"MsoAssignmentMethod","access":"read/write"},{"name":"ContentBits","kind":"property","declaredType":"Long","access":"read/write"},{"name":"Creator","kind":"property","declaredType":"Long","access":"read-only"},{"name":"IsEnabled","kind":"property","declaredType":"Boolean","access":"read/write"},{"name":"Justification","kind":"property","declaredType":"String","access":"read/write"},{"name":"LabelId","kind":"property","declaredType":"String","access":"read/write"},{"name":"LabelName","kind":"property","declaredType":"String","access":"read/write"},{"name":"SetDate","kind":"property","declaredType":"String","access":"read/write"},{"name":"SiteId","kind":"property","declaredType":"String","access":"read/write"}],"doc":{"summary":"Represents the label information data object.","remarks":"The LabelInfo object can be passed to SetLabel method of SensitivityLabel object.","example":"Sub SetLabelInfo()\n\n Dim myLabelInfo As Office.LabelInfo\n Set myLabelInfo = Application.ActiveDocument.SensitivityLabel.CreateLabelInfo()\n With myLabelInfo\n  .ActionId = \"5cc46055-305d-4bc1-8f5f-5edf82231378\"\n  .AssignmentMethod = MsoAssignmentMethod.PRIVILEGED\n  .ContentBits = 4\n  .IsEnabled = True\n  .Justification = \"Some justification needed only if downgrading label.\"\n  .LabelId = \"9203368f-916c-4d59-8292-9f1c6a1e8f39\"\n  .LabelName = \"MyLabelName\"\n  .SetDate = Now()\n  .SiteId = \"6c15903a-880e-4e17-818a-6cb4f7935615\"\n End With\n\nEnd Sub","params":[],"source":"external"}},
			"Office.LanguageSettings": {"displayName":"LanguageSettings","members":[{"name":"Application","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Gets an Application object that represents the container application for the LanguageSettings object (you can use this property with an Automation object to return that object's container application). Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Gets a 32-bit integer that indicates the application in which the LanguageSettings object was created. Read-only.","params":[],"source":"external"}},{"name":"LanguageID","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Gets an MsoAppLanguageID constant representing the locale identifier (LCID) for the install language, the user interface language, or the Help language. Read-only.","params":[],"source":"external"}},{"name":"LanguagePreferredForEditing","kind":"property","declaredType":"Boolean","access":"read-only","doc":{"summary":"Gets True if the value for the MsoLanguageID constant has been identified in the Windows registry as a preferred language for editing. Read-only.","params":[],"source":"external"}},{"name":"Parent","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Gets the Parent object for the ODSOFilter object. Read-only.","params":[],"source":"external"}}],"doc":{"summary":"Returns information about the language settings in a Microsoft Office application.","remarks":"Use Application.LanguageSettings.LanguageID(_MsoAppLanguageID_), where MsoAppLanguageID is a constant used to return locale identifier (LCID) information to the specified application.","example":"MsgBox \"The following locale IDs are registered \" & _\n \"for this application: Install Language - \" & _\n Application.LanguageSettings.LanguageID(msoLanguageIDInstall) & _\n \" User Interface Language - \" & _\n Application.LanguageSettings.LanguageID(msoLanguageIDUI) & _\n \" Help Language - \" & _\n Application.LanguageSettings.LanguageID(msoLanguageIDHelp)","params":[],"source":"external"}},
